-- ==================================================================
-- 시드 데이터 단일 파일 (00_cleanup ~ 10_pairing_audit 을 그대로 이어 붙인 것)
--
--   sqlplus -S 계정/비밀번호@//호스트:1521/서비스명 @seed_all_in_one.sql
--
-- run_all.sql 과 내용은 같다. 파일을 여러 개 옮기기 번거로울 때 쓴다.
-- 총 2595건. 몇 번을 실행해도 결과가 같다(맨 앞에서 시드를 지우고 다시 넣는다).
-- ==================================================================


-- ##################################################################
-- ## 00_cleanup.sql
-- ##################################################################
-- ==================================================================
-- 00. 시드 데이터 삭제 (재실행용)
--
-- 시드 데이터는 전부 PK 990000 이상을 쓴다. 앱이 만드는 데이터는 identity
-- 시퀀스가 1부터 올라가므로 이 범위와 겹치지 않는다.
-- 그래서 "id >= 990000" 만으로 시드만 안전하게 지울 수 있다.
--
-- 예외: screen_time_setting 은 V13 이 GENERATED AS IDENTITY(= ALWAYS) 로
--       만들어서 id 를 지정할 수 없다. child_id 범위로 지운다.
--
-- 자식 → 부모 순서로 지운다(FK 때문).
-- ==================================================================
SET DEFINE OFF

-- 커뮤니티
DELETE FROM community_post_like            WHERE id      >= 990000;
DELETE FROM community_post_comment         WHERE id      >= 990000;
DELETE FROM community_post_attachment      WHERE post_id >= 990000;
DELETE FROM community_post_link            WHERE post_id >= 990000;
DELETE FROM admin_post_report              WHERE id      >= 990000;
DELETE FROM admin_comment_report           WHERE id      >= 990000;
DELETE FROM admin_community_member_ban     WHERE id      >= 990000;
DELETE FROM community_post                 WHERE id      >= 990000;

-- 1:1 문의 / 공지 (V9 에서 board → inquiry 로 바뀌었다)
DELETE FROM inquiry_answer                 WHERE id         >= 990000;
DELETE FROM inquiry_attachment             WHERE inquiry_id >= 990000;
DELETE FROM inquiry                        WHERE id         >= 990000;
DELETE FROM notice_attachment              WHERE notice_id  >= 990000;
DELETE FROM notice_link                    WHERE notice_id  >= 990000;
DELETE FROM notice                         WHERE id         >= 990000;

-- 알림
DELETE FROM notification_setting_toggle    WHERE notification_setting_id >= 990000;
DELETE FROM notification_setting           WHERE id      >= 990000;
DELETE FROM notification                   WHERE id      >= 990000;
DELETE FROM device_token                   WHERE id      >= 990000;

-- 모니터링 / 기기
DELETE FROM app_usage                      WHERE id      >= 990000;
DELETE FROM screenshot                     WHERE id      >= 990000;
DELETE FROM device_event                   WHERE id      >= 990000;

-- 유해차단 / 앱통제
DELETE FROM block_rule                     WHERE id      >= 990000;
DELETE FROM harmful_keyword                WHERE id      >= 990000;
DELETE FROM installed_app                  WHERE id      >= 990000;
DELETE FROM app_control_rule               WHERE id      >= 990000;
DELETE FROM screen_time_setting            WHERE child_id BETWEEN 990200 AND 990299;

-- 위치
DELETE FROM place_event                    WHERE id      >= 990000;
DELETE FROM place                          WHERE id      >= 990000;
DELETE FROM track_segment                  WHERE id      >= 990000;
DELETE FROM tracking_setting               WHERE id      >= 990000;

-- 결제 / 지갑
DELETE FROM qr_payment                     WHERE id      >= 990000;
DELETE FROM store_terminal                 WHERE id      >= 990000;
DELETE FROM wallet_transaction             WHERE id      >= 990000;
DELETE FROM pg_webhook_event               WHERE id      >= 990000;
DELETE FROM charge_order                   WHERE id      >= 990000;
DELETE FROM card                           WHERE id      >= 990000;
DELETE FROM wallet                         WHERE id      >= 990000;

-- 페어링 / 감사로그 / 인증
DELETE FROM pairing_code                   WHERE id        >= 990000;
DELETE FROM admin_audit_log                WHERE id        >= 990000;
DELETE FROM email_verification             WHERE id        >= 990000;
DELETE FROM refresh_token                  WHERE member_id >= 990000;

-- 회원 (자녀 → 부모 순서, parent_id 자기참조 FK)
DELETE FROM member                         WHERE id BETWEEN 990200 AND 990299;
DELETE FROM member                         WHERE id >= 990000;

COMMIT;


-- ##################################################################
-- ## 01_member.sql
-- ##################################################################
-- ==================================================================
-- 01. 회원 (member) — 관리자 4 / 부모 45 / 자녀 45
--
--   비밀번호는 전부 평문 'Test1234!' (AuthService 가 평문 비교한다)
--
--   ID 규칙
--     990001~990004 : 관리자 4종 (SUPER / GENERAL / COMMUNITY / INQUIRY)
--     990101~990145 : 부모 45명 (parent01 ~ parent45)
--     990201~990245 : 자녀 45명 (child01 ~ child45)
--
--   부모-자녀 매핑
--     parent01 → child01, child02, child03   (다자녀 3명)
--     parent21 → child21, child22            (다자녀 2명)
--     parent02~18 → child04~child20          (1:1, 17쌍)
--     parent22~44 → child23~child45          (1:1, 23쌍)
--     parent19, parent20, parent45 → 자녀 없음 (빈 목록 확인용)
--
--   ⚠️ 자녀는 반드시 부모와 함께 다뤄야 한다. 이 시드는 "부모-자녀는 이어져
--      있는데 지갑·알림설정·기기토큰은 비어 있는" 상태를 만들지 않는다.
--      02 이후의 모든 파일이 자녀 45명 · 부모 45명 전원을 빠짐없이 채운다.
--
--   ⚠️ 탈퇴(is_deleted=1) 회원은 일부러 넣지 않았다.
--      WithdrawnMemberCleanupScheduler 가 1분마다 돌면서 "탈퇴 후 10분 지난"
--      계정을 물리 삭제하기 때문에, 넣어 두면 곧 사라지거나 FK 때문에
--      삭제가 실패해 에러 로그만 쌓인다. 탈퇴 흐름은 API 로 테스트할 것.
-- ==================================================================
SET DEFINE OFF


-- ---------------- 관리자 4명 ----------------

-- ---------------- 부모 45명 ----------------

-- ---------------- 자녀 45명 (email 은 NULL — CHILD 는 이메일 없이 가입) ----------------

COMMIT;


-- ##################################################################
-- ## 02_wallet.sql
-- ##################################################################
-- ==================================================================
-- 02. 지갑 (wallet / wallet_transaction / charge_order / pg_webhook_event)
--
--   wallet             90건 : 부모 45 + 자녀 45 (owner_id 는 unique)
--   wallet_transaction 231건 : 부모 45명 · 자녀 45명 전원이 최소 1건을 갖는다
--   charge_order       68건 : parent01 24건(상태 전부) + 부모 44명 각 1건(PAID)
--   pg_webhook_event   60건 : 웹훅 수신 기록(CONFIRMED / MARKED_FAILED /
--                             IGNORED_STATUS / IGNORED_NOT_READY / ORDER_NOT_FOUND)
--
--   ID 규칙
--     wallet             990001~990045 = 부모01~45, 990046~990090 = 자녀01~45
--     wallet_transaction 990001~         지갑 id 순서 · 지갑 안에서는 시간순
--     charge_order       990001~
--     pg_webhook_event   990001~
--
--   ⚠️ 정합성 (99_verify.sql 이 전 지갑에 대해 검사한다)
--     - 잔액(balance)은 그 지갑 마지막 원장의 balance_after 와 정확히 같다.
--       잔액을 먼저 정하고 원장을 끼워 맞춘 것이 아니라, 원장을 쌓아 잔액을
--       역산했다. 그래서 "잔액은 있는데 내역이 비어 있는" 지갑이 없다.
--     - 부모-자녀 이체는 반드시 짝(TRANSFER_OUT/TRANSFER_IN)으로 넣는다.
--       자녀가 있는 부모 42명 전원이 자기 자녀에게 이체한 이력을 갖는다.
--     - ref_uid 규칙은 앱과 동일하다. CHARGE/REFUND=merchantUid,
--       TRANSFER_IN/OUT=상대 ownerId, PAYMENT/PAYMENT_CANCEL=qrToken,
--       ADJUST=조정 사유(호환을 위해 memo 와 같은 값을 넣는다).
--     - memo 는 V15 에 추가된 컬럼이다. 관리자 충전취소(REFUND)와 잔액조정
--       (ADJUST)에만 채우고 나머지는 NULL 이다 — 앱의 저장 방식과 같다.
--     - PAYMENT 계열 ref_uid 는 03_qrpay.sql 의 qr_token 과 짝이 맞는다.
--     - CHARGE 원장은 PAID/REFUNDED 주문과 merchant_uid 로 1:1 이다.
--
--   ⚠️ ChargeOrderExpiryScheduler 가 10분마다 "READY + 30분 경과" 주문을
--      EXPIRED 로 바꾼다. 그래서 READY 는 적용 시점(LOCALTIMESTAMP)으로 1건만
--      넣었고, 오래 방치된 건은 처음부터 EXPIRED 로 넣었다.
--
--   ⚠️ card 테이블은 여기서 만들지 않는다. 카드번호·비밀번호앞2·생년월일·
--      소유자명이 EncryptedStringConverter(AES-256-GCM) 로 암호화 저장되어
--      SQL 로는 올바른 암호문을 만들 수 없다. 카드는 반드시
--      POST /api/wallet/cards API 로 등록할 것.
-- ==================================================================
SET DEFINE OFF


-- ---------------- 지갑 : 부모 45 + 자녀 45 (잔액은 아래 원장에서 역산한 값이다) ----------------

-- ---------------- 원장 : 지갑 90개 전부 (지갑당 최소 1건, 시간순으로 id 가 올라간다) ----------------
-- parent01·child01 은 화면 시연용으로 20건 이상 깊게, 나머지는 흐름이 이어지는 최소 건수.

-- ---------------- 충전 주문 68건 (CANCELLED 4 / EXPIRED 3 / FAILED 4 / PAID 55 / READY 1 / REFUNDED 1) ----------------
-- PAID/REFUNDED 는 원장 CHARGE 와 merchant_uid 로 짝이 맞는다. 나머지 상태는 원장이 없다.

-- ---------------- PG 웹훅 수신 기록 60건 ----------------
-- CONFIRMED 34 : PAID/REFUNDED 주문에 대응 / MARKED_FAILED 4 : FAILED 주문
-- IGNORED_STATUS 7 : paid 가 아닌 상태 통지 / IGNORED_NOT_READY 9 : 이미 처리된 주문에 중복 통지
-- ORDER_NOT_FOUND 6 : 우리 주문번호가 아닌 통지 (signature_provided=0 이 3건)

COMMIT;


-- ##################################################################
-- ## 03_qrpay.sql
-- ##################################################################
-- ==================================================================
-- 03. QR 결제 (store_terminal / qr_payment)
--
--   store_terminal 60건 : ACTIVE 55 / REVOKED 5
--   qr_payment     72건 : 자녀 45명 전원이 결제 이력을 갖는다
--                         (CANCELLED 1 / EXPIRED 4 / ISSUED 3 / PAID 64)
--
--   ID 규칙
--     store_terminal 990001~990060
--     qr_payment     990001~  (자녀 id · 시간 순)
--
--   ⚠️ 정합성
--     - PAID/CANCELLED 의 qr_token·amount 는 02_wallet.sql 의 PAYMENT /
--       PAYMENT_CANCEL 원장과 1:1 로 맞춰 두었다. 관리자 매장결제 목록
--       (GET /api/admin/finance/payments) 이 qr_token 으로 원장을 조인해
--       "결제 후 잔액" 을 뽑으므로 이게 어긋나면 잔액 칸이 빈다.
--     - 결제 금액은 그 시점 자녀 잔액을 넘지 않는다. 부모 이체(TRANSFER_IN)가
--       먼저 있고 그 뒤에 결제가 오도록 시간 순서를 잡았다.
--     - qr_token 형식은 앱과 동일한 "qr_{childId}_{millis}" 를 따른다.
--     - EXPIRED/ISSUED 는 결제되지 않았으므로 원장이 없다.
--     - ISSUED 3건은 expires_at 이 미래라 "결제 대기" 로 조회된다.
--       (적용 시점 기준 +5/+10/+30분. 지나면 다시 실행할 것)
-- ==================================================================
SET DEFINE OFF


-- ---------------- 매장 단말 60건 (terminal_token unique) ----------------

-- ---------------- QR 결제 72건 — 자녀 45명 전원 ----------------
-- child01 25건(시연용) / child02 3 / child03 2 / 나머지 자녀 42명 각 1건.

COMMIT;


-- ##################################################################
-- ## 04_location.sql
-- ##################################################################
-- ==================================================================
-- 04. 위치 (place / place_event / track_segment / tracking_setting)
--
--   place            62건 : child01 16 / child02 2 / child03 2 / 나머지 42명 각 1
--   place_event      68건 : child01 20 / child02 3 / child03 3 / 나머지 42명 각 1
--   track_segment    72건 : child01 20 / child02 5 / child03 5 / 나머지 42명 각 1
--   tracking_setting 45건 : 자녀 45명 각 1건 (child_id unique)
--
--   ⚠️ 자녀 45명 전원이 등록공간·출입이벤트·동선을 최소 1건씩 갖는다.
--      부모 화면에서 자녀를 아무나 골라도 지도가 비지 않게 하기 위한 것이다.
--      place_event.place_id 는 반드시 같은 자녀의 place 를 가리킨다.
--      ARRIVED 는 DESTINATION 공간에만, ENTER/EXIT 는 GEOFENCE 공간에만 붙인다.
--
--   ⚠️ 보관기간 주의
--     TrackRetentionScheduler 가 매일 03시에 created_at 이 3일보다 오래된
--     track_segment 를 지운다(kidhack.location.retention-days=3).
--     그래서 동선은 전부 "적용 시점 기준 최근 100분" 으로 넣는다.
--     며칠 뒤 다시 보려면 이 파일만 다시 실행하면 된다.
--
--   좌표는 자녀(=부모)의 주소지 시·도 기준점 근처로 흩어 둔다.
--   child01 만 서울 송파구 일대(잠실역~석촌호수~방이동)로 촘촘히 잡았다.
-- ==================================================================
SET DEFINE OFF


-- ---------------- 등록 공간 : child01 16건 ----------------

-- ---------------- 등록 공간 : child02 2건 / child03 2건 / 나머지 자녀 42명 각 1건 ----------------

-- ---------------- 공간 출입 이벤트 : child01 20건 (최근 7일) ----------------

-- ---------------- 공간 출입 이벤트 : child02 3건 / child03 3건 / 나머지 자녀 42명 각 1건 ----------------

-- ---------------- 동선 : child01 20건 (5분 간격, 최근 100분) ----------------
-- latitude/longitude 는 varchar2 컬럼이다(엔티티가 String). 문자열로 넣는다.

-- ---------------- 동선 : child02 5건 / child03 5건 / 나머지 자녀 42명 각 1건 (전부 최근 100분 안) ----------------

-- ---------------- 실시간 추적 설정 : 자녀 45명 (child_id unique) ----------------

COMMIT;


-- ##################################################################
-- ## 05_monitoring.sql
-- ##################################################################
-- ==================================================================
-- 05. 모니터링 (app_usage / screenshot / device_event)
--
--   app_usage    70건 : child01 20 / child02 4 / child03 4 / 나머지 42명 각 1
--   screenshot   68건 : child01 20 / child02 3 / child03 3 / 나머지 42명 각 1
--                       (child01 은 SCHEDULED 14 / MANUAL 6)
--   device_event 66건 : child01 18(단말 3대) / child02 3 / child03 3 / 나머지 42명 각 1
--
--   ⚠️ 자녀 45명 전원이 세 테이블 모두에 최소 1건을 갖는다. 관리자 고객관리에서
--      아무 자녀나 열어도 "기기 없음 / 사용기록 없음" 이 뜨지 않게 하기 위한 것이다.
--
--   ⚠️ 보관기간 주의
--     UsageRetentionScheduler 가 매일 04시에 created_at 이 7일보다 오래된
--     app_usage 를 지운다(kidhack.monitoring.retention-days=7).
--     그래서 사용 기록은 전부 최근 6일 안쪽으로 넣는다.
--
--   ⚠️ image_path 는 실제 파일이 없는 더미 경로다. 목록 조회는 정상이지만
--      이미지를 실제로 내려받으면 404 가 난다. 형식은 앱이 저장하는
--      "/api/files/{category}/{filename}" (StoredObject.publicPath) 과 같다.
--
--   device_event 는 관리자 고객관리 > 기기 목록(GET /api/admin/members/
--   customers/{id}/devices)에서 device_id 별 최근 1건만 보여준다.
--   → child01 은 이벤트 18건이지만 기기 목록에는 3행이 뜬다.
-- ==================================================================
SET DEFINE OFF


-- ---------------- 앱 사용량 : child01 20건 (최근 6일) ----------------

-- ---------------- 앱 사용량 : child02 4건 / child03 4건 / 나머지 자녀 42명 각 1건 ----------------

-- ---------------- 스크린샷 : child01 20건 (SCHEDULED 14 / MANUAL 6) ----------------

-- ---------------- 스크린샷 : child02 3건 / child03 3건 / 나머지 자녀 42명 각 1건 ----------------

-- ---------------- 단말 이벤트 : child01 18건 (기기 3대) ----------------

-- ---------------- 단말 이벤트 : child02 3건 / child03 3건 / 나머지 자녀 42명 각 1건 ----------------

