-- ##################################################################
-- ## 06_filtering_appcontrol.sql
-- ##################################################################
-- ==================================================================
-- 06. 유해차단 · 앱통제
--     (harmful_keyword / block_rule / installed_app / app_control_rule /
--      screen_time_setting)
--
--   harmful_keyword     60건 : 전역 차단 키워드 (keyword unique)
--   block_rule          62건 : child01 14 / child02 3 / child03 3 / 나머지 42명 각 1
--   installed_app       68건 : child01 20 / child02 3 / child03 3 / 나머지 42명 각 1
--                              (child_id + package_name unique)
--   app_control_rule    66건 : child01 20 / child02 2 / child03 2 / 나머지 42명 각 1
--   screen_time_setting 45건 : 자녀 45명 (child_id unique)
--
--   ⚠️ app_control_rule 의 package_name 은 반드시 그 자녀의 installed_app 에
--      있는 것만 쓴다. 설치되지 않은 앱에 통제 규칙이 걸려 있으면 앱 통제
--      화면에서 앱 이름이 비어 보인다.
--
--   ⚠️ screen_time_setting 은 id 를 넣지 않는다.
--      V13 이 "GENERATED AS IDENTITY" (= GENERATED ALWAYS) 로 만들어서
--      id 를 직접 지정하면 ORA-32795(생성 열에 값을 삽입할 수 없음)가 난다.
--      그래서 이 테이블만 시드 id 규칙(990000+)에서 빠지고,
--      cleanup 도 child_id 범위로 지운다.
-- ==================================================================
SET DEFINE OFF


-- ---------------- 유해 키워드 60건 (keyword unique) ----------------

-- ---------------- 차단 규칙 : child01 14건 ----------------

-- ---------------- 차단 규칙 : child02 3건 / child03 3건 / 나머지 자녀 42명 각 1건 ----------------

-- ---------------- 설치된 앱 : child01 20건 (child_id + package_name unique) ----------------

-- ---------------- 설치된 앱 : child02 3건 / child03 3건 / 나머지 자녀 42명 각 1건 ----------------

-- ---------------- 앱 통제 규칙 : child01 20건 (daily_limit_minutes=0 이면 완전 차단) ----------------

-- ---------------- 앱 통제 규칙 : child02 2건 / child03 2건 / 나머지 자녀 42명 각 1건 ----------------

