INSERT INTO community_post (id, member_id, title, content, created_at, updated_at) VALUES (990001, 990101, '초등 3학년 스마트폰 사용시간 어떻게 정하세요?', '평일 1시간, 주말 2시간으로 정했는데 매번 실랑이가 벌어집니다. 다른 집은 어떻게 하시는지 궁금해요.', LOCALTIMESTAMP - NUMTODSINTERVAL(40, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(40, 'DAY'));
INSERT INTO community_post (id, member_id, title, content, created_at, updated_at) VALUES (990002, 990101, '지오펜스 반경은 몇 미터가 적당할까요', '학교를 200미터로 잡았더니 운동장 끝에서 진입/이탈 알림이 번갈아 옵니다. 줄이는 게 나을까요?', LOCALTIMESTAMP - NUMTODSINTERVAL(38, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(38, 'DAY'));
INSERT INTO community_post (id, member_id, title, content, created_at, updated_at) VALUES (990003, 990101, '용돈은 주 단위가 좋을까요 월 단위가 좋을까요', '주급으로 주다가 월급으로 바꿨는데 첫 주에 다 써버리네요. 경험 나눠 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(36, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(36, 'DAY'));
INSERT INTO community_post (id, member_id, title, content, created_at, updated_at) VALUES (990004, 990101, '앱 통제 한도를 0분으로 두면 아이가 눈치채나요', '완전 차단으로 걸어 뒀더니 앱이 아예 안 열린다고 하더군요. 미리 이야기하고 거는 편이 낫겠습니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(34, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(34, 'DAY'));
INSERT INTO community_post (id, member_id, title, content, created_at, updated_at) VALUES (990005, 990101, '자녀가 위치 공유를 껐을 때 어떻게 대응하세요', '트래킹 불가 알림이 오면 바로 전화하는 편입니다. 다그치지 않는 게 오래 가더라고요.', LOCALTIMESTAMP - NUMTODSINTERVAL(32, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(32, 'DAY'));
INSERT INTO community_post (id, member_id, title, content, created_at, updated_at) VALUES (990006, 990102, '스마트폰 사용시간, 다들 어떻게 쓰고 계신가요', '스마트폰 사용시간을 켜 두긴 했는데 우리 집에만 맞는 방법인지 모르겠습니다. 다른 분들 설정이 궁금해요.', LOCALTIMESTAMP - NUMTODSINTERVAL(38, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(38, 'DAY'));
INSERT INTO community_post (id, member_id, title, content, created_at, updated_at) VALUES (990007, 990103, '지오펜스 알림, 다들 어떻게 쓰고 계신가요', '지오펜스 알림을 켜 두긴 했는데 우리 집에만 맞는 방법인지 모르겠습니다. 다른 분들 설정이 궁금해요.', LOCALTIMESTAMP - NUMTODSINTERVAL(37, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(37, 'DAY'));
