INSERT INTO community_post_comment (id, post_id, member_id, content, created_at, updated_at) VALUES (990066, 990006, 990117, '유해 사이트 차단 관련해서는 설정 화면에서 한 번 더 확인해 보세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(37, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(37, 'DAY'));
INSERT INTO community_post_comment (id, post_id, member_id, content, created_at, updated_at) VALUES (990067, 990007, 990120, '아이 나이에 따라 많이 다른 것 같습니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(36, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(36, 'DAY'));
INSERT INTO community_post_comment (id, post_id, member_id, content, created_at, updated_at) VALUES (990068, 990008, 990123, '경험 공유 감사합니다. 저희 집에도 적용해 보겠습니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(35, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(35, 'DAY'));
INSERT INTO community_post_comment (id, post_id, member_id, content, created_at, updated_at) VALUES (990069, 990009, 990126, '처음엔 저도 헷갈렸는데 며칠 쓰니 익숙해지더군요.', LOCALTIMESTAMP - NUMTODSINTERVAL(34, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(34, 'DAY'));
INSERT INTO community_post_comment (id, post_id, member_id, content, created_at, updated_at) VALUES (990070, 990010, 990129, '너무 통제하면 역효과가 나서 요즘은 대화를 더 하려고 합니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(33, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(33, 'DAY'));
INSERT INTO community_post_comment (id, post_id, member_id, content, created_at, updated_at) VALUES (990071, 990011, 990132, '기기 배터리를 켜 두면 배터리가 조금 더 닳는 느낌입니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(32, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(32, 'DAY'));
INSERT INTO community_post_comment (id, post_id, member_id, content, created_at, updated_at) VALUES (990072, 990012, 990135, '저희는 한 달에 한 번 규칙을 다시 정합니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(31, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(31, 'DAY'));
