INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990031, 990031, '페어링 코드는 발급 후 유효시간이 지나면 자동 삭제됩니다. 코드 발급 화면을 다시 열어 새 코드로 시도해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(17, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(17, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990032, 990032, '결제 승인과 지갑 반영 사이에 최대 1분 정도 지연이 있을 수 있습니다. 그래도 반영되지 않으면 주문번호를 알려주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(16, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(16, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990033, 990033, '이체는 부모 지갑 잔액에서 빠져나갑니다. 충전 대기(READY) 상태 금액은 잔액에 포함되지 않습니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(15, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(15, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990034, 990034, '충전 내역 화면에서 해당 주문의 환불 버튼으로 신청하실 수 있습니다. 전액 환불만 지원합니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(14, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(14, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990035, 990035, '자녀 기기의 알림 권한과 화면 캡처 권한이 모두 켜져 있어야 합니다. 설정에서 확인해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(13, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(13, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990036, 990036, '해당 기능은 자녀 기기에 앱이 실행 중이어야 동작합니다. 백그라운드 실행 제한을 해제해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(12, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(12, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990037, 990037, '말씀하신 증상은 최신 버전에서 수정되었습니다. 앱을 업데이트한 뒤 다시 확인해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(11, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(11, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990038, 990038, '설정 > 알림에서 해당 유형이 꺼져 있으면 목록에 표시되지 않습니다. 토글을 확인해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(10, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(10, 'DAY'));
