INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990002, '개인정보 처리방침 개정 안내', '위치정보 보관 기간이 명확해졌습니다. 자세한 내용은 첨부된 문서를 확인해 주세요.', 990002, LOCALTIMESTAMP + NUMTODSINTERVAL(1979884, 'DAY'), LOCALTIMESTAMP + NUMTODSINTERVAL(1979884, 'DAY'));
INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990003, '루키즈페이 카드 등록 기능 오픈', '이제 앱에서 카드를 등록해 바로 충전할 수 있습니다.', 990001, LOCALTIMESTAMP + NUMTODSINTERVAL(1979886, 'DAY'), LOCALTIMESTAMP + NUMTODSINTERVAL(1979886, 'DAY'));
